local pCgrUX = 44

return (function(bytecode, key_mod)
    -- Environment Check (Anti-Debug sederhana)
    if not game then return end 
    
    local bit_xor = bit32 and bit32.bxor or function(a,b) 
        -- Fallback XOR manual yang BENAR (bukan a+b)
